CREATE TABLE "Tenant" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL, "slug" TEXT NOT NULL UNIQUE, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "User" ("id" TEXT NOT NULL PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "displayName" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Membership" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "userId" TEXT NOT NULL, "role" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Membership_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE, CONSTRAINT "Membership_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE, CONSTRAINT "Membership_tenantId_userId_key" UNIQUE ("tenantId","userId"));
CREATE TABLE "Methodology" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "code" TEXT NOT NULL, "version" TEXT NOT NULL, "name" TEXT NOT NULL, "status" TEXT NOT NULL, "definition" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Methodology_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE, CONSTRAINT "Methodology_tenantId_code_version_key" UNIQUE ("tenantId","code","version"));
CREATE TABLE "RegulatoryRequirement" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "authority" TEXT NOT NULL, "jurisdiction" TEXT NOT NULL, "instrument" TEXT NOT NULL, "version" TEXT NOT NULL, "status" TEXT NOT NULL, "sourceRef" TEXT NOT NULL, "effectiveFrom" TIMESTAMP(3), "effectiveTo" TIMESTAMP(3), "definition" JSONB NOT NULL, "checksum" TEXT NOT NULL, "capturedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "RegulatoryRequirement_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE, CONSTRAINT "RegulatoryRequirement_tenantId_instrument_version_key" UNIQUE ("tenantId","instrument","version"));
CREATE TABLE "Evidence" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "type" TEXT NOT NULL, "title" TEXT NOT NULL, "uri" TEXT NOT NULL, "contentHash" TEXT NOT NULL, "classification" TEXT NOT NULL, "sourceSystem" TEXT NOT NULL, "sourceRecordId" TEXT, "capturedAt" TIMESTAMP(3) NOT NULL, "metadata" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Evidence_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE TABLE "Provenance" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "objectType" TEXT NOT NULL, "objectId" TEXT NOT NULL, "parentIds" JSONB NOT NULL, "transformationIds" JSONB NOT NULL, "contentHash" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Provenance_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE TABLE "EmissionFactor" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "factorSet" TEXT NOT NULL, "factorCode" TEXT NOT NULL, "version" TEXT NOT NULL, "gas" TEXT NOT NULL, "value" DECIMAL(30,12) NOT NULL, "unit" TEXT NOT NULL, "geography" TEXT, "validFrom" TIMESTAMP(3) NOT NULL, "validTo" TIMESTAMP(3), "sourceSystem" TEXT NOT NULL, "sourceRef" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmissionFactor_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE TABLE "Activity" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "activityType" TEXT NOT NULL, "quantity" DECIMAL(30,12) NOT NULL, "unit" TEXT NOT NULL, "startAt" TIMESTAMP(3) NOT NULL, "endAt" TIMESTAMP(3) NOT NULL, "facilityId" TEXT, "assetId" TEXT, "sourceSystem" TEXT NOT NULL, "sourceRecordId" TEXT, "status" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Activity_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE TABLE "EmissionResult" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "activityId" TEXT NOT NULL, "factorId" TEXT NOT NULL, "methodologyId" TEXT NOT NULL, "methodologyVersion" TEXT NOT NULL, "co2eKg" DECIMAL(30,12) NOT NULL, "inputSnapshotHash" TEXT NOT NULL, "trace" JSONB NOT NULL, "calculatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "EmissionResult_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE, CONSTRAINT "EmissionResult_activityId_fkey" FOREIGN KEY ("activityId") REFERENCES "Activity"("id") ON DELETE RESTRICT, CONSTRAINT "EmissionResult_factorId_fkey" FOREIGN KEY ("factorId") REFERENCES "EmissionFactor"("id") ON DELETE RESTRICT);
CREATE TABLE "IntegrationConnector" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "sourceSystem" TEXT NOT NULL, "schemaVersion" TEXT NOT NULL, "connectorVersion" TEXT NOT NULL, "status" TEXT NOT NULL, "config" JSONB NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "IntegrationConnector_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL PRIMARY KEY, "tenantId" TEXT NOT NULL, "actorId" TEXT NOT NULL, "action" TEXT NOT NULL, "objectType" TEXT NOT NULL, "objectId" TEXT NOT NULL, "previousHash" TEXT, "eventHash" TEXT NOT NULL, "correlationId" TEXT NOT NULL, "payload" JSONB NOT NULL, "occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AuditEvent_tenantId_fkey" FOREIGN KEY ("tenantId") REFERENCES "Tenant"("id") ON DELETE CASCADE);
CREATE INDEX "Activity_tenantId_startAt_idx" ON "Activity"("tenantId","startAt");
CREATE INDEX "EmissionResult_tenantId_calculatedAt_idx" ON "EmissionResult"("tenantId","calculatedAt");
CREATE INDEX "Evidence_tenantId_capturedAt_idx" ON "Evidence"("tenantId","capturedAt");
CREATE INDEX "AuditEvent_tenantId_occurredAt_idx" ON "AuditEvent"("tenantId","occurredAt");